/// <returns>ThrowExceptionTaskUms</returns>
public static boolean throwExceptionTaskUms()
{
    NDXBatchProcessingParameters nDXBatchProcessingParameters = NDXBatchProcessingParameters::find(false);
    nDXBatchProcessingParameters.reread();
    return (nDXBatchProcessingParameters.ThrowExceptionTaskUms == NoYes::Yes);
}
